import { chromium } from "playwright";
import { mkdir } from "node:fs/promises";
import path from "node:path";

const BASE_URL = process.env.SOTS_URL || "http://127.0.0.1:5050";
const OUT_PATH =
  process.env.OUT_PATH ||
  "/Users/sinchunyeung/github/personal-page/assets/projects/sots-preview.png";

async function main() {
  await mkdir(path.dirname(OUT_PATH), { recursive: true });

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
  });

  await page.goto(BASE_URL, { waitUntil: "networkidle" });
  await page.waitForFunction(() => {
    const select = document.querySelector("#traceSelect");
    return select && select.options.length > 1;
  });

  await page.selectOption("#traceSelect", "51");
  await page.click("#loadBtn");

  await page.waitForFunction(() =>
    document.body.classList.contains("trace-loaded-mobile")
  );
  await page.waitForTimeout(500);

  await page.click("#mobilePanelClose");
  await page.waitForTimeout(200);

  for (let i = 0; i < 4; i++) {
    const forward = page.locator("#mobileStepForwardBtn");
    if (await forward.isDisabled()) break;
    await forward.click();
    await page.waitForTimeout(250);
  }

  await page.screenshot({
    path: OUT_PATH,
    type: "png",
    fullPage: false,
  });

  await browser.close();
  console.log(`Saved screenshot to ${OUT_PATH}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

