import { chromium } from "playwright";
import { mkdir } from "node:fs/promises";
import path from "node:path";

const BASE_URL = process.env.SOTS_URL || "http://127.0.0.1:63612";
const OUT_PATH =
  process.env.OUT_PATH ||
  "/Users/sinchunyeung/github/personal-page/assets/projects/sots-preview.png";

async function main() {
  await mkdir(path.dirname(OUT_PATH), { recursive: true });

  const browser = await chromium.launch({ headless: true });
  // Desktop layout shows the algorithm scene + controls that define the project.
  const page = await browser.newPage({
    viewport: { width: 1280, height: 800 },
    deviceScaleFactor: 2,
  });

  await page.goto(BASE_URL, { waitUntil: "networkidle" });
  await page.waitForFunction(() => {
    const select = document.querySelector("#traceSelect");
    return select && select.options.length > 1;
  });

  await page.selectOption("#traceSelect", "53");
  await page.click("#loadBtn");

  // Wait until streaming steps are available.
  await page.waitForFunction(() => {
    const t = window.__SOTS_WAIT__;
    return false;
  }, null, { timeout: 1000 }).catch(() => {});

  await page.waitForFunction(() => {
    // Trace finished loading when the play button is enabled or status shows loaded.
    const play = document.querySelector("#playBtn");
    return play && !play.disabled;
  }, { timeout: 60000 });

  await page.waitForTimeout(600);

  // Ensure key algorithm layers are visible.
  await page.evaluate(() => {
    const on = [
      "toggle-stream",
      "toggle-simplified",
      "toggle-ball-p0",
      "toggle-ball-pi",
      "toggle-Gi",
      "toggle-F",
      "toggle-S",
      "toggle-P",
    ];
    for (const id of on) {
      const el = document.getElementById(id);
      if (el && !el.checked) el.click();
    }
  });

  // Jump into a mid-stream step where free-space / candidates are interesting.
  for (let i = 0; i < 18; i++) {
    const forward = page.locator("#stepForwardBtn");
    if (await forward.isDisabled()) break;
    await forward.click();
    await page.waitForTimeout(80);
  }

  await page.evaluate(() => {
    const fitBtn = document.getElementById("fitBtn");
    if (fitBtn) fitBtn.click();
  });
  await page.waitForTimeout(400);

  // Capture the canvas region (the important part), with a little chrome.
  const canvasWrap = page.locator("#canvasWrap, #canvasContainer, main").first();
  if (await canvasWrap.count()) {
    await canvasWrap.screenshot({ path: OUT_PATH, type: "png" });
  } else {
    await page.screenshot({ path: OUT_PATH, type: "png", fullPage: false });
  }

  await browser.close();
  console.log(`Saved screenshot to ${OUT_PATH}`);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

